catalog_script_client.script:
function onLoad() {
    var userLang = g_lang;

    if (userLang == "en") {
        g_form.setLabelOf('manager', 'Manager (not informed without your consent)');
        g_form.setLabelOf('room_and_floor', 'Specify location (office, room, floor, etc.)');
        g_form.setLabelOf('contact_information', 'Preferred contact information (personal email, cell phone number)');
    } else { 
	    g_form.setLabelOf('manager', 'Gestionnaire (ne sera pas informé sans votre consentement)');
        g_form.setLabelOf('room_and_floor', "Précisez l'emplacement (bureau, salle, étage, etc.) ");
        g_form.setLabelOf('contact_information', 'Coordonnées privilégiées (courriel personnel, numéro de téléphone cellulaire)');
	}
}
